def make_station_id(row):
    # Handle NaN location
    loc = "" if pd.isna(row.location) else str(row.location)
    # Construct NET.STA.LOC. - matching PhaseNet output style
    if loc == "":
        return f"{row.network}.{row.station}."
    else:
        return f"{row.network}.{row.station}.{loc}."

stations['id'] = stations.apply(make_station_id, axis=1)
